from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid semantic version: {text!r}")

    major, minor, patch, prerelease, build = match.groups()
    prerelease_parts = tuple(prerelease.split(".")) if prerelease else ()
    for part in prerelease_parts:
        if part.isdigit() and len(part) > 1 and part[0] == "0":
            raise ValueError(
                f"numeric pre-release identifier has a leading zero: {part!r}"
            )

    return Version(
        major=int(major),
        minor=int(minor),
        patch=int(patch),
        prerelease=prerelease_parts,
        build=tuple(build.split(".")) if build else (),
    )


def _coerce(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _compare_pre_release(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for left, right in zip(a, b):
        left_numeric = left.isdigit()
        right_numeric = right.isdigit()

        if left_numeric and right_numeric:
            left_value, right_value = int(left), int(right)
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        else:
            left_value, right_value = left, right

        if left_value < right_value:
            return -1
        if left_value > right_value:
            return 1

    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left, right = _coerce(a), _coerce(b)

    for left_part, right_part in (
        (left.major, right.major),
        (left.minor, right.minor),
        (left.patch, right.patch),
    ):
        if left_part < right_part:
            return -1
        if left_part > right_part:
            return 1

    return _compare_pre_release(left.prerelease, right.prerelease)


@dataclass(frozen=True)
class _Comparator:
    operator: str
    version: Version


def _parse_comparator(token: str) -> _Comparator:
    for operator in (">=", "<=", ">", "<", "=", "^", "~"):
        if token.startswith(operator):
            version_text = token[len(operator) :]
            break
    else:
        operator = ""
        version_text = token

    if not version_text:
        raise ValueError(f"invalid comparator: {token!r}")
    return _Comparator(operator, parse(version_text))


def _parse_range(range_: str) -> list[list[_Comparator]]:
    sets: list[list[_Comparator]] = []
    for chunk in range_.split("||"):
        tokens = chunk.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append([_parse_comparator(token) for token in tokens])
    return sets


def _matches_comparator(version: Version, comparator: _Comparator) -> bool:
    operator = comparator.operator
    other = comparator.version

    if operator in ("", "="):
        return compare(version, other) == 0
    if operator == ">":
        return compare(version, other) > 0
    if operator == ">=":
        return compare(version, other) >= 0
    if operator == "<":
        return compare(version, other) < 0
    if operator == "<=":
        return compare(version, other) <= 0

    if operator == "^":
        if other.major != 0:
            upper = Version(other.major + 1, 0, 0)
        elif other.minor != 0:
            upper = Version(0, other.minor + 1, 0)
        else:
            upper = Version(0, 0, other.patch + 1)
    elif operator == "~":
        upper = Version(other.major, other.minor + 1, 0)
    else:  # pragma: no cover - _parse_comparator only produces known operators
        raise ValueError(f"unknown operator: {operator!r}")

    return compare(version, other) >= 0 and compare(version, upper) < 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _coerce(version)
    comparator_sets = _parse_range(range_)

    for comparators in comparator_sets:
        if candidate.prerelease:
            allowed = any(
                comparator.version.prerelease
                and (
                    comparator.version.major,
                    comparator.version.minor,
                    comparator.version.patch,
                )
                == (candidate.major, candidate.minor, candidate.patch)
                for comparator in comparators
            )
            if not allowed:
                continue

        if all(_matches_comparator(candidate, comparator) for comparator in comparators):
            return True

    return False

