from __future__ import annotations

from datetime import datetime, timedelta

_MONTHS = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_WEEKDAYS = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_FIELD_SPECS = (
    (0, 59, None),  # minute
    (0, 23, None),  # hour
    (1, 31, None),  # day of month
    (1, 12, _MONTHS),  # month
    (0, 7, _WEEKDAYS),  # day of week
)


def _parse_value(text: str, low: int, high: int, names: dict[str, int] | None) -> int:
    if not text:
        raise ValueError("empty value")
    if names is not None and text.upper() in names:
        value = names[text.upper()]
    else:
        if not text.isascii() or not text.isdigit():
            raise ValueError(f"invalid value: {text!r}")
        value = int(text)

    if value < low or value > high:
        raise ValueError(f"value out of range: {text!r}")
    return value


def _parse_field(
    field: str, low: int, high: int, names: dict[str, int] | None
) -> set[int]:
    values: set[int] = set()

    for item in field.split(","):
        if not item:
            raise ValueError("empty field item")

        if "/" in item:
            pieces = item.split("/")
            if len(pieces) != 2:
                raise ValueError(f"invalid step: {item!r}")
            base, step_text = pieces
            if not base:
                raise ValueError(f"invalid step: {item!r}")
            if not step_text.isascii() or not step_text.isdigit():
                raise ValueError(f"invalid step: {item!r}")
            step = int(step_text)
            if step <= 0:
                raise ValueError(f"invalid step: {item!r}")
        else:
            base, step = item, None

        if base == "*":
            start, end = low, high
        elif "-" in base:
            if base.count("-") != 1:
                raise ValueError(f"invalid range: {base!r}")
            start_text, end_text = base.split("-")
            start = _parse_value(start_text, low, high, names)
            end = _parse_value(end_text, low, high, names)
            if start > end:
                raise ValueError(f"invalid range: {base!r}")
        else:
            start = _parse_value(base, low, high, names)
            end = high if step is not None else start

        if step is None:
            values.update(range(start, end + 1))
        else:
            values.update(range(start, end + 1, step))

    return values


def _five_years_after(moment: datetime) -> datetime:
    try:
        return moment.replace(year=moment.year + 5)
    except ValueError:  # February 29
        return moment.replace(year=moment.year + 5, day=28)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected five fields, got {len(fields)}")

    parsed = [
        _parse_field(field, low, high, names)
        for field, (low, high, names) in zip(fields, _FIELD_SPECS)
    ]
    minutes, hours, days_of_month, months, days_of_week = parsed
    days_of_week = {0 if day == 7 else day for day in days_of_week}

    day_of_month_restricted = fields[2] != "*"
    day_of_week_restricted = fields[4] != "*"

    first_minute = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    deadline = _five_years_after(after)

    date = first_minute.date()
    last_date = deadline.date()
    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)

    while date <= last_date:
        if date.month in months:
            day_of_month_matches = date.day in days_of_month
            day_of_week_matches = (date.weekday() + 1) % 7 in days_of_week

            if day_of_month_restricted and day_of_week_restricted:
                day_matches = day_of_month_matches or day_of_week_matches
            else:
                day_matches = day_of_month_matches and day_of_week_matches

            if day_matches:
                for hour in sorted_hours:
                    for minute in sorted_minutes:
                        candidate = datetime(
                            date.year,
                            date.month,
                            date.day,
                            hour,
                            minute,
                            tzinfo=after.tzinfo,
                        )
                        if candidate < first_minute:
                            continue
                        if candidate > deadline:
                            raise ValueError(
                                f"no matching time within five years: {expression!r}"
                            )
                        return candidate

        date += timedelta(days=1)

    raise ValueError(f"no matching time within five years: {expression!r}")

