from __future__ import annotations

import re

_ALIGNMENTS = ("left", "right", "center")
_DELIMITER_RE = re.compile(r"^:?-+:?$")


def _cell_text(value: object) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter(width: int, alignment: str | None) -> str:
    chars = ["-"] * width
    if alignment in ("left", "center"):
        chars[0] = ":"
    if alignment in ("right", "center"):
        chars[-1] = ":"
    return "".join(chars)


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        if not isinstance(align, list) or len(align) != columns:
            raise ValueError("align must have one entry per column")
        if any(value not in _ALIGNMENTS and value is not None for value in align):
            raise ValueError("invalid alignment")
        alignments = list(align)

    normalized_rows: list[list[str]] = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        values = [_cell_text(value) for value in row]
        values.extend([""] * (columns - len(values)))
        normalized_rows.append(values)

    header_cells = [_cell_text(value) for value in header]
    widths = []
    for index, cell in enumerate(header_cells):
        width = len(cell)
        for row in normalized_rows:
            width = max(width, len(row[index]))
        widths.append(max(3, width))

