def _interpolate(
    value: str,
    section: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
) -> str:
    result: list[str] = []
    index = 0

    while index < len(value):
        char = value[index]
        if char != "$":
            result.append(char)
            index += 1
            continue

        if index + 1 < len(value) and value[index + 1] == "$":
            result.append("$")
            index += 2
            continue

        if index + 1 >= len(value) or value[index + 1] != "{":
            result.append("$")
            index += 1
            continue

        end = value.find("}", index + 2)
        if end == -1:
            result.append("$")
            index += 1
            continue

        reference = value[index + 2 : end]
        if ":" in reference:
            reference_section, reference_key = reference.split(":", 1)
        else:
            reference_section, reference_key = section, reference
        reference_key = reference_key.lower()

        target = (reference_section, reference_key)
        if reference_section not in sections or reference_key not in sections[reference_section]:
            raise InterpolationError(
                f"missing reference: {reference_section}:{reference_key}"
            )
        if target in active:
            raise InterpolationError(
                f"interpolation cycle at {reference_section}:{reference_key}"
            )

        result.append(
            _resolve(reference_section, reference_key, sections, cache, active)
        )
        index = end + 1

    return "".join(result)


def _resolve(
    section: str,
    key: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
) -> str:
    target = (section, key)
    if target in cache:
        return cache[target]
    if target in active:
        raise InterpolationError(f"interpolation cycle at {section}:{key}")

    active.add(target)
    try:
        resolved = _interpolate(sections[section][key], section, sections, cache, active)
    finally:
        active.remove(target)

    cache[target] = resolved
    return resolved


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    continued_key: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        stripped = raw_line.strip()

        if not stripped or stripped[0] in "#;":
            continued_key = None
            continue

        if raw_line[0].isspace() and continued_key is not None:
            assert current_section is not None
            sections[current_section][continued_key] += "\n" + stripped
            continue

        continued_key = None

        if stripped.startswith("[") and stripped.endswith("]"):
            current_section = stripped[1:-1].strip()
            sections.setdefault(current_section, {})
            continue

        separator = -1
        for index, char in enumerate(stripped):
            if char in "=:":
                separator = index
                break

        if separator == -1:
            raise ParseError(lineno, "expected a section, key, or continuation")

        key = stripped[:separator].strip().lower()
        value = stripped[separator + 1 :].strip()
        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key before any section")

        sections[current_section][key] = value
        continued_key = key

    cache: dict[tuple[str, str], str] = {}
    resolved: dict[str, dict[str, str]] = {}
    for section, values in sections.items():
        resolved[section] = {
            key: _resolve(section, key, sections, cache, cache and set())
            for key in values
        }
    return resolved

